import { test, expect } from '@playwright/test';

test.describe('Footer Links Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com');
  });

  test('should navigate to the About Us page when About Us link is clicked', async ({ page }) => {
    await page.getByText('About Us').click();
    await expect(page).toHaveURL('https://example.com/about');
    await expect(page.getByRole('heading', { name: /about us/i })).toBeVisible();
  });

  test('should navigate to the Contact page when Contact link is clicked', async ({ page }) => {
    await page.getByText('Contact').click();
    await expect(page).toHaveURL('https://example.com/contact');
    await expect(page.getByRole('heading', { name: /contact/i })).toBeVisible();
  });
});
